import { test } from "node:test";
import assert from "node:assert/strict";
import { SwiftShipAdapter, mapStatus, type HttpGet } from "../src/carrier/swiftShipAdapter.ts";
import { CarrierUnavailableError } from "../src/carrier/types.ts";
import { cheapestWithin, parseRates } from "../src/carrier/rates.ts";
import { notifyIfDelivered } from "../src/notifyDelivered.ts";
import { pollOpenShipments, type Shipment } from "../src/shipments/poller.ts";

const respond = (status: number, body: unknown = {}): HttpGet => async () => ({ status, body });
const tracking = (...codes: string[]) => ({
    tracking_no: "SS123",
    events: codes.map((code, i) => ({ code, occurred_at: `2026-11-0${i + 1}T09:00:00Z` })),
    estimated_delivery: "2026-11-09",
});

// A carrier whose answer depends on the tracking number.
const routes = (byNumber: Record<string, [number, unknown?]>): HttpGet => async (url) => {
    const number = decodeURIComponent(url.split("/").pop()!);
    const [status, body] = byNumber[number] ?? [404];
    return { status, body: body ?? {} };
};

function memoryRepo(shipments: Shipment[]) {
    const rows = new Map(shipments.map((s) => [s.id, { ...s }]));
    return {
        rows,
        listOpen: async () => [...rows.values()].filter((s) => s.open),
        update: async (id: string, changes: Partial<Shipment>) => void rows.set(id, { ...rows.get(id)!, ...changes }),
    };
}
const shipment = (id: string, trackingNumber: string): Shipment => ({
    id, trackingNumber, customerEmail: `${id}@example.com`, status: "in_transit", open: true, lastCheckedAt: null,
});

test("known SwiftShip codes map to our statuses", () => {
    assert.equal(mapStatus("PU"), "in_transit");
    assert.equal(mapStatus("OFD"), "out_for_delivery");
    assert.equal(mapStatus("DL"), "delivered");
    assert.equal(mapStatus("RTS"), "exception");
    assert.equal(mapStatus(undefined), "label_created");
});

test("a code we have never seen is not reported as delivered", () => {
    console.log("HLD (held at customs) maps to:", mapStatus("HLD"));
    assert.equal(mapStatus("HLD"), "unknown");
});

test("track() uses the latest event, returns null for unknown parcels, and raises on outages", async () => {
    const info = await new SwiftShipAdapter("https://api.swiftship.test", respond(200, tracking("LC", "PU", "OFD"))).track("SS123");
    assert.deepEqual(info, { trackingNumber: "SS123", status: "out_for_delivery", lastEventAt: "2026-11-03T09:00:00Z", etaDate: "2026-11-09" });
    assert.equal(await new SwiftShipAdapter("https://x.test", respond(404)).track("nope"), null);
    await assert.rejects(new SwiftShipAdapter("https://x.test", respond(503)).track("SS123"), CarrierUnavailableError);
    await assert.rejects(new SwiftShipAdapter("https://x.test", respond(429)).track("SS123"), CarrierUnavailableError);
});

test("no delivery email for a parcel held at customs", async () => {
    const sent: string[] = [];
    const mailer = { send: async (to: string) => void sent.push(to) };
    const carrier = new SwiftShipAdapter("https://x.test", respond(200, tracking("LC", "PU", "HLD")));
    const notified = await notifyIfDelivered(carrier, mailer, { trackingNumber: "SS123", customerEmail: "a@example.com" });
    assert.equal(notified, false);
    assert.deepEqual(sent, []);
});

test("rate quotes are parsed to cents and filtered to services we sell", () => {
    const quotes = parseRates({
        rates: [
            { service_code: "SSG", total_charge: "8.29", currency: "USD", transit_days: 5 },
            { service_code: "SSX", total_charge: "19.10", currency: "USD", transit_days: 2 },
            { service_code: "SSO", total_charge: "41.00", currency: "USD", transit_days: null },
            { service_code: "FREIGHT", total_charge: "300.00", currency: "USD", transit_days: 9 },
        ],
    });
    assert.deepEqual(quotes.map((q) => [q.serviceLevel, q.priceCents]), [["ground", 829], ["express", 1910]]);
    assert.equal(cheapestWithin(quotes, 3)?.serviceLevel, "express");
    assert.equal(cheapestWithin(quotes, 7)?.serviceLevel, "ground");
    assert.equal(cheapestWithin(quotes, 1), null);
});

test("the poller emails and closes delivered shipments and skips carrier outages", async () => {
    const repo = memoryRepo([shipment("s1", "DELIVERED1"), shipment("s2", "DOWN"), shipment("s3", "MOVING")]);
    const sent: string[] = [];
    const carrier = new SwiftShipAdapter("https://x.test", routes({
        DELIVERED1: [200, { ...tracking("PU", "DL"), tracking_no: "DELIVERED1" }],
        DOWN: [503],
        MOVING: [200, { ...tracking("PU", "IT"), tracking_no: "MOVING" }],
    }));
    const summary = await pollOpenShipments(repo, carrier, { send: async (to) => void sent.push(to) }, () => new Date("2026-11-10T00:00:00Z"));
    assert.deepEqual(summary, { checked: 2, changed: 1, delivered: 1, skipped: 1 });
    assert.deepEqual(sent, ["s1@example.com"]);
    assert.equal(repo.rows.get("s1")?.open, false);
    assert.equal(repo.rows.get("s3")?.lastCheckedAt, "2026-11-10T00:00:00.000Z");
});

test("the poller keeps a parcel held at customs open", async () => {
    const repo = memoryRepo([shipment("s1", "HELD")]);
    const sent: string[] = [];
    const carrier = new SwiftShipAdapter("https://x.test", routes({ HELD: [200, { ...tracking("PU", "HLD"), tracking_no: "HELD" }] }));
    await pollOpenShipments(repo, carrier, { send: async (to) => void sent.push(to) }, () => new Date("2026-11-10T00:00:00Z"));
    assert.deepEqual(sent, []);
    assert.equal(repo.rows.get("s1")?.open, true);
    assert.equal(repo.rows.get("s1")?.status, "unknown");
});
